//! Generated / minified file detection (upstream `generated-detection.ts`). A relevance
//! hint: generated nodes stay in the graph but rank last.

use regex::{Regex, RegexSet};
use std::sync::OnceLock;

fn path_set() -> &'static RegexSet {
    static SET: OnceLock<RegexSet> = OnceLock::new();
    SET.get_or_init(|| {
        RegexSet::new([
            r"\.pb\.go$",
            r"\.pulsar\.go$",
            r"_grpc\.pb\.go$",
            r"_mock\.go$",
            r"_mocks\.go$",
            r"^mock_[^/]+\.go$",
            r"\.generated\.[jt]sx?$",
            r"\.gen\.[jt]sx?$",
            r"\.pb\.[jt]s$",
            r"_pb\.[jt]s$",
            r"_grpc_pb\.[jt]s$",
            r"[.-]min\.m?js$",
            r"_pb2(_grpc)?\.py$",
            r"_pb2\.pyi$",
            r"\.pb\.(cc|h)$",
            r"\.g\.cs$",
            r"Grpc\.cs$",
            r"OuterClass\.java$",
            r"Grpc\.java$",
            r"\.pb\.swift$",
            r"\.g\.dart$",
            r"\.freezed\.dart$",
            r"\.pb\.dart$",
            r"\.pbgrpc\.dart$",
            r"\.chopper\.dart$",
            r"\.generated\.rs$",
        ])
        .expect("generated path patterns")
    })
}

/// Path-only check (cheap enough for a sort comparator).
pub fn is_generated_path(path: &str) -> bool {
    path_set().is_match(path)
}

const HEADER_SCAN_CHARS: usize = 8192;
const HEADER_SCAN_LINES: usize = 60;

fn content_patterns() -> &'static Vec<Regex> {
    static PATTERNS: OnceLock<Vec<Regex>> = OnceLock::new();
    PATTERNS.get_or_init(|| {
        [
            r"(?i)\bcode generated\b.{0,200}?\bdo not edit\b",
            r"(?i)\b(?:automatically |auto[- ]?)?generated (?:by|from|with)\b.{0,200}?\bdo not (?:edit|modify|change)\b",
            r"(?:^|[^\p{L}\p{N}_@])@generated\b",
            r"(?i)<auto-?generated\s*/?>",
            r"(?i)\b(?:automatically generated|auto[- ]?generated|autogenerated) by\b",
            r"(?i)\bgenerated by\s+\S.{0,80}?\bby running\b",
            r"(?i)\bthis (?:file|class|code|module) (?:is|was) (?:auto[- ]?)?generated\b",
            r"(?i)\bdo not (?:edit|modify)\b.{0,120}?\b(?:auto[- ]?generated|generated file|generated code)\b",
        ]
        .iter()
        .map(|p| Regex::new(p).expect("generated header pattern"))
        .collect()
    })
}

fn comment_leader() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| {
        Regex::new(r#"(?i)^\s*(?://|/\*+|\*+/?|#+|--+|<!--|%+|;+|'|!|\(\*|\{-|"""|'''|=begin|<#|@rem\b|rem\b)"#)
            .expect("comment leader")
    })
}

const BLOCK_DELIMS: [(&str, &str); 6] =
    [("/*", "*/"), ("<!--", "-->"), ("\"\"\"", "\"\"\""), ("'''", "'''"), ("=begin", "=end"), ("<#", "#>")];

/// Banner in the head of the file ("Code generated ... DO NOT EDIT.", `@generated`, ...).
pub fn has_generated_header(content: &str) -> bool {
    if content.is_empty() {
        return false;
    }
    let mut end = content.len().min(HEADER_SCAN_CHARS);
    while !content.is_char_boundary(end) {
        end -= 1;
    }
    let head = &content[..end];
    // Cheap pre-filter: every marker contains the stem "generat".
    if !head.to_ascii_lowercase().contains("generat") {
        return false;
    }
    let leader = comment_leader();
    let patterns = content_patterns();
    let mut open: Option<(&str, &str)> = None;
    for line in head.split('\n').take(HEADER_SCAN_LINES) {
        let in_block = open.is_some();
        if (in_block || leader.is_match(line)) && patterns.iter().any(|p| p.is_match(line)) {
            return true;
        }
        if let Some((_, close)) = open {
            if line.contains(close) {
                open = None;
            }
            continue;
        }
        for (o, c) in BLOCK_DELIMS {
            if let Some(at) = line.find(o) {
                if !line[at + o.len()..].contains(c) {
                    open = Some((o, c));
                }
                break;
            }
        }
    }
    false
}

const MINIFIED_LINE_CHARS: usize = 1000;

/// A minified or bundled script that is not named so (webpack runtime, or most of the text on
/// very long lines dense with `;{}(),`).
pub fn is_minified_content(path: &str, content: &str) -> bool {
    let lower = path.to_ascii_lowercase();
    let scriptish = lower.ends_with(".js") || lower.ends_with(".mjs") || lower.ends_with(".cjs");
    if !scriptish || content.len() < 4 * MINIFIED_LINE_CHARS {
        return false;
    }
    if content.contains("function __webpack_require__") {
        return true;
    }
    let (mut long, mut punct) = (0usize, 0usize);
    for line in content.split('\n') {
        if line.len() >= MINIFIED_LINE_CHARS {
            long += line.len();
            punct += line.bytes().filter(|b| matches!(b, b';' | b'{' | b'}' | b'(' | b')' | b',')).count();
        }
    }
    long as f64 >= content.len() as f64 * 0.5 && punct as f64 >= long as f64 * 0.03
}

pub fn detect_generated(path: &str, content: &str) -> bool {
    is_generated_path(path) || has_generated_header(content) || is_minified_content(path, content)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn path_patterns() {
        assert!(is_generated_path("api/foo.pb.go"));
        assert!(is_generated_path("web/app.min.js"));
        assert!(is_generated_path("x/service_pb2.py"));
        assert!(!is_generated_path("src/main.go"));
    }

    #[test]
    fn headers() {
        assert!(has_generated_header("// Code generated by protoc-gen-go. DO NOT EDIT.\npackage x\n"));
        assert!(has_generated_header("/* @generated */\nexport const x = 1;"));
        assert!(has_generated_header("# This file was auto-generated by tool\nx = 1\n"));
        assert!(!has_generated_header("package main\n// regular file\nfunc generateThing() {}\n"));
        assert!(!has_generated_header(""));
    }

    #[test]
    fn minified() {
        let long = format!("{}\n", "a(b);".repeat(1000));
        assert!(is_minified_content("x.js", &long));
        assert!(!is_minified_content("x.ts", &long));
        assert!(!is_minified_content("x.js", "const a = 1;\n"));
    }
}
